mapper.select:
SELECT cf.id, cf.customer_id, cf.caregiver_id, cf.focus_level, cf.focus_reason, cf.focus_content, cf.start_date, cf.end_date, cf.status, cf.created_at, cf.updated_at, c.name as customer_name, u.real_name as caregiver_name, b.bed_number, r.room_number FROM customer_focus cf JOIN customers c ON cf.customer_id = c.id JOIN users u ON cf.caregiver_id = u.id LEFT JOIN beds b ON c.bed_id = b.id LEFT JOIN rooms r ON b.room_id = r.id
AND ( c.name LIKE CONCAT('%', #{searchKeyword}, '%') OR cf.focus_reason LIKE CONCAT('%', #{searchKeyword}, '%') OR cf.focus_content LIKE CONCAT('%', #{searchKeyword}, '%') OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%') OR b.bed_number LIKE CONCAT('%', #{searchKeyword}, '%') )
AND cf.focus_level = #{focusLevel}
AND cf.status = #{status}
AND cf.caregiver_id = #{caregiverId}
AND cf.start_date >= #{startDate}
AND cf.start_date <= #{endDate}
ORDER BY cf.focus_level DESC, cf.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM customer_focus cf
JOIN customers c ON cf.customer_id = c.id
JOIN users u ON cf.caregiver_id = u.id


        AND (
        c.name LIKE CONCAT('%', #{searchKeyword}, '%')
        OR cf.focus_reason LIKE CONCAT('%', #{searchKeyword}, '%')
        OR cf.focus_content LIKE CONCAT('%', #{searchKeyword}, '%')
        OR u.real_name LIKE CONCAT('%', #{searchKeyword}, '%')
        )


        AND cf.focus_level = #{focusLevel}


        AND cf.status = #{status}


        AND cf.caregiver_id = #{caregiverId}


        AND cf.start_date >= #{startDate}


        AND cf.start_date <= #{endDate}

mapper.update:
UPDATE customer_focus
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT cf.*, c.name as customer_name, u.real_name as caregiver_name, b.bed_number, r.room_number FROM customer_focus cf JOIN customers c ON cf.customer_id = c.id JOIN users u ON cf.caregiver_id = u.id LEFT JOIN beds b ON c.bed_id = b.id LEFT JOIN rooms r ON b.room_id = r.id WHERE cf.caregiver_id = #{caregiverId}
AND cf.status = #{status}
ORDER BY CASE cf.focus_level WHEN '高' THEN 1 WHEN '中' THEN 2 WHEN '低' THEN 3 ELSE 4 END, cf.start_date DESC

SELECT * FROM customer_focus
WHERE customer_id = #{customerId}
  AND caregiver_id = #{caregiverId}
  AND status = 1
    LIMIT 1

SELECT cf.*, c.name as customer_name, u.real_name as caregiver_name, b.bed_number, r.room_number FROM customer_focus cf JOIN customers c ON cf.customer_id = c.id JOIN users u ON cf.caregiver_id = u.id LEFT JOIN beds b ON c.bed_id = b.id LEFT JOIN rooms r ON b.room_id = r.id WHERE cf.status = 1 AND cf.end_date IS NOT NULL AND cf.end_date <= DATE_ADD(CURDATE(), INTERVAL #{days} DAY)
AND cf.caregiver_id = #{caregiverId}
ORDER BY cf.end_date ASC
